/** the merged-frame polyline for one siberia line, by its bundle name. Built
 *  once, at module load, so every reader shares one array — `pts` identity is
 *  what `world.mjs`'s own fork pass and the trail map both key on. */
export const SIB_LINES = Object.fromEntries(
  SIBERIA_RAW.map((f) => [f.n, { name: f.n, way: f.w, pts: f.p.map(sibToRef) }]));
export const sibByName = (n) => {
  const f = SIB_LINES[n];
  if (!f) throw new Error(`runs-data.mjs: siberia has no line "${n}"`);
  return f;
};

// ===========================================================================
// specs/0078 W3 — THE NORTH REGION'S REGISTER, ADDITIVE AND SEPARATE.
//
// Same shape and same discipline as the siberia block above, one frame west and
// north: a FRAME row of three declared numbers, a MAP derived from those numbers
// and this world's own, a RAW table of frame-local vertices copied
// vertex-for-vertex out of runs/palisades-north-A-raw-01/scene/runs-data.mjs,
// and one `nbToRef` applied once at load.
//
// Nothing here is re-surveyed and nothing here is a second transform.
// ===========================================================================
export const NORTH_FRAME = { id: 'north', lat0: 39.19748792564466, lon0: -120.27176690231781, z0: 2328.8 };

// THE MAP, DERIVED HERE FROM THE TWO ORIGINS — never transcribed.
//
//     s  = cos(lat0_red-dog) / cos(lat0_north)     = 1.000078534
//     ox = (mercX(lon_nb) - mercX(lon_rd)) * cos0_rd = -3510.315 m
//     oy = (mercY(lat_nb) - mercY(lat_rd)) * cos0_rd =  +614.277 m
//     dz = z0_nb - z0_rd = +438.8 m
//
// `s` is ABOVE one here where siberia's is below it, and that is the sign check
// 0052 W0's inverted-scale defect was found by: the north frame is FARTHER from
// the equator than the reference (39.19749 vs 39.19197), so cos(REF)/cos(north)
// is greater than one. `renders/0078/w0-probe.mjs` re-derives all four numbers,
// proves the derivation by reproducing GATE-0052-W0's published siberia
// constants to the printed digit, and lands the Gold Coast Funitel TOP terminal
// 0.035 m from this world's own independently surveyed `A.funTop`.
export const NB_MAP = (() => {
  const c0 = Math.cos(REF_FRAME.lat0 * D2R), cN = Math.cos(NORTH_FRAME.lat0 * D2R);
  return {
    s: c0 / cN,
    ox: (mercX(NORTH_FRAME.lon0) - mercX(REF_FRAME.lon0)) * c0,
    oy: (mercY(NORTH_FRAME.lat0) - mercY(REF_FRAME.lat0)) * c0,
    dz: NORTH_FRAME.z0 - REF_FRAME.z0,
  };
})();

/** one north-local point -> this world's ENU, rounded to the centimetre. */
export const nbToRef = ([x, y, z]) => [
  +(NB_MAP.s * x + NB_MAP.ox).toFixed(2),
  +(NB_MAP.s * y + NB_MAP.oy).toFixed(2),
  +(z + NB_MAP.dz).toFixed(2),
];

