export const NB_LINES = Object.fromEntries(
  NORTH_RAW.map((f) => [f.n + (f.k === 'lift' ? ' (lift)' : ''),
    { name: f.n, way: f.w, kind: f.k, pts: f.p.map(nbToRef),
      nodes: f.nodes ? f.nodes.map(nbToRef) : null }]));
export const nbByName = (n) => {
  const f = NB_LINES[n];
  if (!f) throw new Error(`runs-data.mjs: no north line "${n}" (have ${Object.keys(NB_LINES).join(', ')})`);
  return f;
};
